              kind: "prose",
              length: "A4 2/5 분량",
              text: "운명이나 운수에 대해서는 알 수 없지만, 대체로 정부 체계가 튼튼할수록 오랜 역사가 지속되는 듯하다. 혹자는 대통령을 선출하는 외국의 사례를 들어, 우리도 대통령을 뽑는 정치체로 가야 한다고 주장한다. 이로 인하여 임금에 대한 반항과 각종 망동이 나타나게 된다. 그러나 어지러운 마음의 사람들이 하는 말에 현혹되어서는 안 된다. 미국과 같이 인구가 많다면 그 중 학식과 덕망이 높은 사람이 있어 이러한 사람을 미국의 대통령으로 선출할 수 있다. 그들은 대통령제를 하는 국가는 그 나름의 역사적 연유가 있음을 모르고 그러한 설을 펼치는 것이다. 인구가 많은 나라에서는 현인이 나타나기도 쉬우므로, 그들은 그러한 제도를 뽑아서도 나라를 건전하게 유지할 수 있는 것이다. 이런 사정과 무관하게, 우리나라에도 대통령제를 도입해야 한다고 운운하는 것은 역사적 연유에 무지한 것이다. 임금이 다스리는 정부 하의 국민은 그와 같은 주장하는 어리석은 사람을 반박하고 제도를 더욱더 답습해야 한다. 견고히 세습을 유지하고 어질고 능력 있는 사람 중에서 관리를 선출해야 한다. 국가발전을 유지하고 안정된 법체계로 기존의 방식을 유지해야 한다. 우리가 지금 해야 할 일은 그러한 일에 관하여 논쟁을 하기보다는, 우수한 인재를 선발하고 경제를 개발시키며 청렴한 국가로 나아가는 것이다. 그리고 역대 임금들의 공덕을 기리면서 나라를 지속하고 덕을 높여 만천하에 알려야 한다.",
