              kind: "prose",
              text: `계약에 있어서 핵심 정보를 공유하는 것은 중요한 부분을 차지한다. 그런데 상대방에게 정보 공유를 요구할 권리가 있는가? 이에 대해 갑, 을, 병은 다음과 같은 시각을 제기한다.
갑: 정보소유자가 취득을 위해 높은 비용과 많은 노력을 들인 정보는 고지하지 않아도 되지만, 우연히 얻은 정보는 고지해야 한다. 비용을 들여서 취득한 정보를 타인에게 고지하도록 하면 정보 취득을 위해 노력할 유인이 사라져 사회적으로 긍정적인 효과를 얻을 수 없다. 그러나 우연히 얻은 정보는 공유해도 그런 유인이 사라지지 않는다.
을: 정보를 통해 백신의 독점적 생산이나 새로운 항로 등과 같이 사회적 효용이 클 것이라면, 정보의 주체는 정보를 공개적으로 고지하지 않고 해당 정보를 사용할 수 있다. 그러나 정보 공개와 고지가 거래가격의 변동으로 이어져서 새로운 부의 재분배를 일으킬 것으로 예상되는 경우에는 정보를 고지해야 한다.
병: 거래의 상대방이 정보를 취득하기 위해 상당한 고비용을 들여야만 한다면, 상대방을 보호하기 위해 정보를 고지해야 한다. 그러나 상대방도 충분히 합리적인 방법으로 취득 가능했으나 그 자신이 소홀해서 인지하지 못한 정보라면 해당 정보를 고지하지 않아도 된다.
[사례 1] 채굴회사 A는 B의 토지를 구매하는 과정에서, 전문업체에 금액을 지불하고 토지 조사를 의뢰하여 B의 토지 100m 아래에 금맥이 있다는 사실을 알게 되었다. 이후 A는 B에게 그 사실을 알리지 않은 채 특별한 프리미엄 없이 토지 매매 계약을 체결했다. B는 뒤늦게 이 사실을 알게 되었고, A에게 토지를 넘겨주는 것을 거부하고 있다.
[사례 2] H 아파트에 거주하는 A는 자신의 아파트 주변에 공동묘지가 지어진 사실을 알리지 않은 채 H 아파트 주변에 살고 있는 B와 계약을 체결했다. 이 사실을 알게 된 B는 공동묘지의 건설 정보를 고지하지 않았다는 이유로 A에게 매매대금 지급을 거부하는 상황이다.`,
