              kind: "prose",
              text: "중국 시진핑 주석이 ‘잔반 줄이기 운동’ 시행을 천명했다. 많은 중국 국민이 다이어트에 돌입한 이유도 이와 무관치 않다. 이후 중국 SNS에서 인기를 끌었던 각종 ‘먹방’ 영상들도 삭제되거나 계정이 중단됐다. 이러한 언급을 한 이유는 첫째, 지방의 홍수 피해 및 메뚜기 떼 피해로 인한 농산물 수확 감소, 둘째, 코로나 19로 인해 각국에서 농산물 수출을 제한하자 중국의 식량 수입이 차질을 빚을 것이란 우려, 셋째, 극단으로 치닫고 있는 미·중 갈등 관계가 식량안보를 둘러싼 경각심을 일깨워준 계기로 보인다.",
