              text: `고대 그리스와 로마 신화에서 여신들은 특정한 상징과 외관을 통해 인간의 다양한 가치와 운명을 표현했다. 포르투나는 로마 신화에서 운명의 여신으로, 인간이 제어할 수 없는 불확실성과 우연성을 상징한다. 그녀는 종종 공 위에 한 발을 올린 채 균형을 유지하는 모습으로 그려지며, 이 모습은 행운이 언제든지 흔들릴 수 있음을 암시한다. 또한, 그녀의 눈은 안대로 가려져 있는데, 이는 행운이 임의적이고 인간의 자격이나 도덕성과는 무관하게 찾아온다는 의미를 담고 있다. 포르투나가 뿌리는 금화는 예기치 않은 순간에 찾아오는 행운과 부를 상징하며, 그녀의 불확실하고 변덕스러운 성격을 더욱 부각시킨다.
반면, 유스티티아는 정의와 공정을 상징하는 여신으로, 법과 윤리를 수호하는 역할을 맡고 있다. 그녀 역시 공 위에 발을 올리고 있는 모습으로 묘사되지만, 이는 흔들림 없는 정의의 균형을 의미한다. 유스티티아는 눈을 가리지 않고 베일을 쓴 모습으로, 외관에 치우치지 않고 진실과 본질을 꿰뚫어보려는 의지를 상징한다. 그녀의 한 손에는 저울이, 다른 손에는 칼이 들려 있는데, 저울은 공정한 판단을, 칼은 정의의 엄정함과 처벌을 나타낸다. 포르투나와는 달리 유스티티아는 공정성과 정의의 원칙에 따라 행동하며, 인간의 도덕적 기준에 부합하는 불변의 가치와 질서를 추구하는 존재로 여겨진다.`,
