              text: "자네들은 인간의 본래 모습이 어떠했는지 그리고 그 모습이 어떤 변화를 겪었는지를 알아야 하네. 오래전 우리 모습은 지금과 같지 않고, 완전히 다른 것이네. 인간의 성은 세 가지가 있어서, 지금처럼 남성과 여성이라는 두 성만 있었던 것이 아니라, 남성과 여성을 가진 세 번째 성이 있었는데 지금은 그 이름인 ‘남녀추니’만 남아있을 뿐이고, 세 번째 성을 지닌 사람은 더 이상 존재하지 않게 됐지. 이렇게 인간이 세 가지 성으로 존재했던 이유는 남성은 원래 해의 자손이었고, 여성은 대지의 자손이었으며, 남녀추니는 달의 자손이었는데, 달은 해와 땅 둘 모두에 관여하기 때문이네, 그들은 능력과 힘이 엄청난데다 야망도 가지고 있었기 때문에 신들까지 공격하려고 했다네. 그래서 제우스와 그 밖의 다른 신들은 그들을 어떻게 해야 할지를 논의했지만, 별다른 방법을 찾지 못해 고민에 빠졌다네. 결국, 제우스는 인간 개개인을 둘로 쪼개어 인간들의 힘을 약하게 만들 뿐만 아니라, 그들의 수를 늘리어 자신들에게 공경과 제사를 바치는 이득을 늘릴 수 있도록 하였다네. 이후 제우스의 지시로 아폴론은 인간들을 두 쪽으로 쪼개고 몸의 모든 곳에 있던 살가죽을 끌어당겨서 지금은 배라고 불리는 곳에 모아서는, 그 중앙에 오늘날 배꼽이라 불리는 주둥이 하나를 만든 후에 한데 묶었다네. 인간의 원래 모습이 둘로 쪼개지자, 사람들은 자신의 반쪽을 그리워하며 만나려고 했고, 서로 부둥켜안고 뒤엉켜서 한 몸이 되고 싶어 했네. 이렇게 해서 아주 오래전부터 사람들은 서로를 열렬히 사랑하려는 에로스의 열망을 지니고 태어난 것이네. 또한, 원래 남자였던 사람에게서 쪼개져 나온 자들은 남자를 쫓아다니지. 그런 자들은 원래 남자였던 사람에게서 쪼개져 나온 토막이기 때문에 소년일 때에는 남자를 좋아해서 남자와 함께 눕고 함께 뒤엉키는 것을 기뻐하는데, 그들이야말로 무척 용감한 기질을 지니고 태어난 자들이어서 청소년 중에서 최고에 속한 자들이네. 아무튼 이러한 이유 때문에 우리는 우리 마음에 본성에 타고난 연인을 찾고자 하는 것이네.",
