              no: 1,
              label: "A",
              kind: "prose",
              text: "‘도시 경쟁력이 곧 국가 경쟁력’이라는 신자유주의 도시관이 이미 전 세계적으로 확산되고 있으며, 기존 시가지 정비가 도시 간 경쟁력의 확보에 최대의 화두로 등장했다. 영국, 미국, 독일, 일본 등에서 낙후된 구시가지의 활력을 불러일으키기 위한 다각적인 노력이 ‘도시 재생’이란 이름으로 시도되고 있다. 국가마다 도시 재생의 도입 배경은 조금씩 다르다. 그러나 20세기 도시문제가 급격한 경제성장 과정에서 사회적 생산기반 부족에 대응한 하드웨어적 정책 중심이라는 것에 비해 최근의 도시 재생의 기본방향은 소프트웨어적 종합대응책 중심이라는 것에 특징이 있다. 즉 도시 재생은 다양한 도시기능의 복원을 의미하는 것으로 기존 도시가 가지고 있는 물리적, 사회적, 경제적 문제를 치유하기 위한 모든 행위를 말하며, 도시재개발, 도시 재활성화, 도시쇄신 등의 복합어들을 포괄하고 있는 종합적 개념이다. 도시 재생의 유형으로는 대상지역의 기능적 특성에 따라 주거지 재생, 상가 재생, 노후산업단지 재생, 역사문화 자원 재생 등으로 분류할 수 있다. 추구하는 목적에 따라 경제 회생과 일자리창출에 주안점을 둔 경제기반 형성형 도시 재생, 주민들의 삶의 질 개선과 커뮤니티 복원에 초점을 둔 마을 만들기형 도시 재생으로 구별할 수 있다. 지금까지 우리나라의 도시 재생정책은 부동산 가치, 주거환경 향상, 도심 활성화의 촉진, 지역 소득 향상 등과 같은 긍정적인 면도 있으나, 주거, 상가의 임대료 인상 등으로 기존 거주민과 기존 상인이 소외되고 지역 공동체의 정체성이 훼손되는 부정적인 문제도 있다.",
